using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1) GetTypeInfo<T> — returns a strongly-typed JsonTypeInfo<T>
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> → Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized: {json}");

Person? roundTripped = JsonSerializer.Deserialize(json, personInfo);
Console.WriteLine($"Deserialized: {roundTripped}");

// 2) TryGetTypeInfo<T> — check-without-throwing
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? found))
{
    Console.WriteLine($"\nTryGetTypeInfo<Person> succeeded → {found!.Type.Name}");
}

// For a type the resolver *can't* resolve we get false instead of an exception.
// A custom options with an empty resolver will fail to resolve anything.
var empty = new JsonSerializerOptions { TypeInfoResolver = new DefaultJsonTypeInfoResolver() };
empty.TypeInfoResolver = JsonTypeInfoResolver.Combine(); // resolver that resolves nothing

if (empty.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? notFound))
{
    Console.WriteLine("Unexpectedly resolved!");
}
else
{
    Console.WriteLine($"\nTryGetTypeInfo<Person> on empty resolver → not available (no exception)");
}

public record Person(string Name, int Age);

